/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** Defaults for list properties; an attribute holds the items comma-separated. */
export type ArrayDefaults = Record<string, string[]>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/** `"a, b"` -> `['a', 'b']`; an absent attribute restores the fallback list. */
function toList(value: string | null, fallback: readonly string[]): string[] {
  if (value === null) return [...fallback];
  return value
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** Order-sensitive comparison, used to skip redundant writes and renders. */
function sameList(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((part, index) => part === b[index]);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 * - `static arrayDefaults` opts an attribute into a comma-separated `string[]`
 *   property. Elements that do not declare it keep a scalar-only API.
 * - `checkValidity()` / `reportValidity()` / `reset()` / `getFormData()` wrap the
 *   platform form surface so a subclass does not repeat it.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /**
   * Array-backed properties and their defaults. The attribute holds the items
   * comma-separated (`items="a, b"`); the property is a `string[]`.
   */
  static arrayDefaults: ArrayDefaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return [
      ...Object.keys(this.defaults).map(toKebabCase),
      ...Object.keys(this.arrayDefaults).map(toKebabCase),
    ];
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #arrayDefaults: ArrayDefaults = {};
  #arrays: Record<string, string[]> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#arrayDefaults = ctor.arrayDefaults;
    this.#arrays = {};
    for (const key of Object.keys(ctor.arrayDefaults)) {
      this.#arrays[key] = [...ctor.arrayDefaults[key]];
    }
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }

    for (const key of Object.keys(ctor.arrayDefaults)) {
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => [...(this.#arrays[key] ?? [])],
        set: (next: string[] | string) => this.#assignList(key, next),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /**
   * Constraint validation in the owning form. Forwards to `ElementInternals`
   * when available; without internals there is nothing to validate, so it
   * reports `true`.
   */
  checkValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.checkValidity !== 'function') return true;
    return internals.checkValidity();
  }

  /** Like `checkValidity()`, but asks the platform to report the problem. */
  reportValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.reportValidity !== 'function') return true;
    return internals.reportValidity();
  }

  /**
   * Resets the control to the state it was mounted with and re-renders.
   * Delegates to `formResetCallback()` so a subclass only overrides
   * `onFormReset()`.
   */
  reset(): void {
    this.formResetCallback();
    this.requestUpdate();
  }

  /**
   * Serializes this element the way `new FormData(form)` would: one row per
   * `formEntries()` entry, or `null` when the element submits nothing.
   */
  getFormData(): FormData | null {
    const entries = this.formEntries();
    if (entries.length === 0) return null;
    const data = new FormData();
    for (const [name, value] of entries) data.append(name, value);
    return data;
  }

  /**
   * Rows this element contributes to `FormData`. Defaults to `name` + `value`
   * when both are usable; subclasses with a richer payload override it.
   */
  protected formEntries(): Array<[string, string | File]> {
    const { name, value } = this as unknown as { name?: unknown; value?: unknown };
    if (typeof name !== 'string' || name.length === 0) return [];
    if (typeof value !== 'string' && typeof value !== 'number') return [];
    return [[name, String(value)]];
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (key in this.#arrayDefaults) {
      this.#arrays[key] = toList(value, this.#arrayDefaults[key]); // attribute -> list property
      if (this.#rendered && !this.#reflecting) this.requestUpdate();
      return;
    }
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assignList(key: string, next: string[] | string): void {
    const value = Array.isArray(next)
      ? next.map((part) => String(part).trim()).filter((part) => part.length > 0)
      : toList(next, []);
    if (sameList(this.#arrays[key] ?? [], value)) return;
    this.#arrays[key] = value;
    this.#reflectList(key, value);
  }

  #reflectList(key: string, value: string[]): void {
    const attribute = toKebabCase(key);
    const fallback = this.#arrayDefaults[key] ?? [];
    this.#reflecting = true;
    try {
      if (value.length === 0 || sameList(value, fallback)) this.removeAttribute(attribute);
      else this.setAttribute(attribute, value.join(','));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

/**
 * Calendar arithmetic for date-based components.
 *
 * Pure functions only: this module never touches the DOM, so it is safe under
 * SSR and in workers. Every operation stays on local calendar fields
 * (`new Date(year, month - 1, day)`) and no `toISOString()` / UTC conversion is
 * involved, so a timezone offset can never move a day by one.
 */

/** Calendar day in `YYYY-MM-DD`. */
export type ISODate = string;

/** Shown in the weekday header, indexed by `Date#getDay()` (0 = Sunday). */
const WEEKDAY_LABELS = ['日', '一', '二', '三', '四', '五', '六'];

const ISO_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Zero-pads to `length` digits; years shorter than 4 digits keep their sign. */
function pad(value: number, length: number): string {
  return String(value).padStart(length, '0');
}

/** Date fields as the components see them; `month` is 1-12. */
interface CalendarParts {
  year: number;
  month: number;
  day: number;
}

/** Days in `month` (1-12) of `year`; `month` overflows into the next year. */
function daysInMonth(year: number, month: number): number {
  return new Date(year, month, 0).getDate();
}

/** Builds a local `Date`; `month` is 1-12, day overflow normalizes like `Date`. */
function toDate({ year, month, day }: CalendarParts): Date {
  const date = new Date(year, month - 1, day);
  // `new Date(0-99, ...)` maps the year to 1900-1999; keep a padded four-digit
  // year for what it says.
  if (year >= 0 && year < 100) date.setFullYear(year);
  return date;
}

/** Local date fields of a `Date`; never routes through UTC. */
function toParts(date: Date): CalendarParts {
  return { year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate() };
}

/** Whether `value` is a real calendar day in `YYYY-MM-DD`. */
export function isValidISO(value: string): boolean {
  return parseISO(value) !== null;
}

/** Parses `YYYY-MM-DD` into local fields, or `null` when it is not a real day. */
export function parseISO(value: string): CalendarParts | null {
  const match = ISO_PATTERN.exec(value);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > 12) return null;
  if (day < 1 || day > daysInMonth(year, month)) return null;
  return { year, month, day };
}

/** Formats local fields as `YYYY-MM-DD` (`month` is 1-12). */
export function formatISO(value: CalendarParts): ISODate {
  return `${pad(value.year, 4)}-${pad(value.month, 2)}-${pad(value.day, 2)}`;
}

/** Today in the user's local timezone. */
export function todayISO(): ISODate {
  return formatISO(toParts(new Date()));
}

/** Shifts `iso` by `delta` days; an invalid input is returned unchanged. */
export function addDays(iso: ISODate, delta: number): ISODate {
  const parts = parseISO(iso);
  if (!parts) return iso;
  return formatISO(toParts(toDate({ ...parts, day: parts.day + delta })));
}

/** Shifts a year/month pair by `delta` months, carrying across year boundaries. */
export function addMonths(
  month: { year: number; month: number },
  delta: number,
): { year: number; month: number } {
  const index = month.year * 12 + (month.month - 1) + delta;
  return { year: Math.floor(index / 12), month: (((index % 12) + 12) % 12) + 1 };
}

/**
 * The 6 x 7 day grid of a month, padded with the neighbouring months.
 * `firstDay` is the weekday column 0 (0 = Sunday, 1 = Monday).
 */
export function monthMatrix(
  year: number,
  month: number,
  firstDay: 0 | 1,
): Array<Array<{ iso: ISODate; inMonth: boolean }>> {
  const weekday = toDate({ year, month, day: 1 }).getDay();
  const offset = (weekday - firstDay + 7) % 7;
  const start = 1 - offset;
  const rows: Array<Array<{ iso: ISODate; inMonth: boolean }>> = [];

  for (let row = 0; row < 6; row += 1) {
    const week: Array<{ iso: ISODate; inMonth: boolean }> = [];
    for (let column = 0; column < 7; column += 1) {
      const date = toDate({ year, month, day: start + row * 7 + column });
      week.push({ iso: formatISO(toParts(date)), inMonth: date.getMonth() === month - 1 });
    }
    rows.push(week);
  }
  return rows;
}

/** Weekday header labels, rotated so column 0 matches `firstDay`. */
export function weekdayLabels(firstDay: 0 | 1): string[] {
  return Array.from({ length: 7 }, (_, index) => WEEKDAY_LABELS[(firstDay + index) % 7]);
}

/** Order-sensitive comparison of two ISO days: `-1`, `0` or `1`. */
export function compareISO(a: ISODate, b: ISODate): number {
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

/** Clamps `value` into `[min, max]`; undefined bounds are ignored. */
export function clampISO(value: ISODate, min?: ISODate, max?: ISODate): ISODate {
  let result = value;
  if (min !== undefined && compareISO(result, min) < 0) result = min;
  if (max !== undefined && compareISO(result, max) > 0) result = max;
  return result;
}

/**
 * Markup builders shared by `<an-date>` and `<an-date-range>`.
 *
 * Pure string functions only: the calendar arithmetic comes from
 * `internal/calendar.ts`, so no component here depends on the DOM and the same
 * grid renders identically in both controls. Every day stays a local calendar
 * field — no `toISOString()` / UTC conversion.
 */

import {
  ISODate,
  addDays,
  compareISO,
  isValidISO,
  monthMatrix,
  parseISO,
  weekdayLabels,
} from '../internal/calendar';

/** One cell of the rendered month grid. */
interface MatrixCell {
  iso: ISODate;
  inMonth: boolean;
}

/** The 6 x 7 grid of a month, padded with the neighbouring months. */
export type CalendarMatrix = MatrixCell[][];

/** First and last day the grid can focus. */
export interface GridBounds {
  first: ISODate;
  last: ISODate;
}

/** Both ends of a painted range; a missing side paints nothing. */
export interface PanelRange {
  start?: ISODate;
  end?: ISODate;
}

/** Everything `renderCalendarPanel` needs; the components own the state. */
export interface CalendarPanelOptions {
  /** Displayed month, 1-12. */
  month: number;
  /** Displayed year. */
  year: number;
  /** Weekday column 0 (0 = Sunday, 1 = Monday). */
  firstDay: 0 | 1;
  /** Endpoints painted as selected. */
  selected: readonly ISODate[];
  /** Range to paint, usually the pending selection plus the hovered day. */
  range: PanelRange | null;
  /** Day that owns the roving `tabindex`; `null` falls back to the first enabled day. */
  focused: ISODate | null;
  /** Earliest selectable day. */
  min?: ISODate;
  /** Latest selectable day. */
  max?: ISODate;
  /** Highlighted as today. */
  today: ISODate;
  /** Disables every day (the control itself is disabled or readonly). */
  blocked: boolean;
  /** Enables the clear button. */
  clear: boolean;
  /** Header title; defaults to `YYYY年M月`. */
  title?: string;
}

/** Escapes text that enters markup as an attribute value or a text node. */
export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => {
    switch (char) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      default:
        return '&#39;';
    }
  });
}

/** Local weekday index of `iso` (0 = Sunday); invalid input reads as Sunday. */
export function weekdayIndex(iso: ISODate): number {
  const parts = parseISO(iso);
  if (!parts) return 0;
  // Local fields only: the UTC-based `Date#getUTCDay()` would shift the day.
  return new Date(parts.year, parts.month - 1, parts.day).getDay();
}

/** First day of the week `iso` belongs to, using the same `firstDay` column. */
export function weekStart(iso: ISODate, firstDay: 0 | 1): ISODate {
  return addDays(iso, -((weekdayIndex(iso) - firstDay + 7) % 7));
}

/** Last day of the week `iso` belongs to, using the same `firstDay` column. */
export function weekEnd(iso: ISODate, firstDay: 0 | 1): ISODate {
  return addDays(iso, 6 - ((weekdayIndex(iso) - firstDay + 7) % 7));
}

/**
 * Renders a day through a display pattern: `YYYY`, `MM`, `M`, `DD` and `D` are
 * replaced, every other character is kept verbatim.
 */
export function formatDisplay(iso: ISODate, format: string): string {
  const parts = parseISO(iso);
  if (!parts) return '';
  const two = (value: number): string => String(value).padStart(2, '0');
  return format
    .replace(/YYYY/g, String(parts.year))
    .replace(/MM/g, two(parts.month))
    .replace(/DD/g, two(parts.day))
    .replace(/M/g, String(parts.month))
    .replace(/D/g, String(parts.day));
}

/** Header title of a month, e.g. `2026年11月`. */
export function monthTitle(year: number, month: number): string {
  return `${year}年${month}月`;
}

/** `true` when the day is outside `min`/`max` or the whole control is blocked. */
export function isBlockedDay(
  iso: ISODate,
  min: ISODate | undefined,
  max: ISODate | undefined,
  blocked: boolean,
): boolean {
  if (blocked) return true;
  if (min !== undefined && compareISO(iso, min) < 0) return true;
  if (max !== undefined && compareISO(iso, max) > 0) return true;
  return false;
}

/** First and last day of a rendered matrix. */
export function gridBounds(rows: CalendarMatrix): GridBounds {
  return { first: rows[0][0].iso, last: rows[rows.length - 1][6].iso };
}

/** Keeps `target` inside the grid and moves it forward to the nearest enabled day. */
export function nearestEnabled(
  target: ISODate,
  bounds: GridBounds,
  blocked: (iso: ISODate) => boolean,
): ISODate {
  let cursor = target;
  for (let step = 0; step < 42; step += 1) {
    if (!blocked(cursor)) return cursor;
    const next = addDays(cursor, 1);
    if (compareISO(next, bounds.last) > 0) break;
    cursor = next;
  }
  cursor = target;
  for (let step = 0; step < 42; step += 1) {
    if (!blocked(cursor)) return cursor;
    const next = addDays(cursor, -1);
    if (compareISO(next, bounds.first) < 0) break;
    cursor = next;
  }
  return target;
}

/**
 * Moves the roving focus by `delta` days, staying inside the grid and skipping
 * blocked days in the direction of travel.
 */
export function stepFocus(
  current: ISODate,
  delta: number,
  bounds: GridBounds,
  blocked: (iso: ISODate) => boolean,
): ISODate {
  const direction = delta >= 0 ? 1 : -1;
  let target = addDays(current, delta);
  if (compareISO(target, bounds.first) < 0) target = bounds.first;
  if (compareISO(target, bounds.last) > 0) target = bounds.last;
  for (let step = 0; step < 42; step += 1) {
    if (!blocked(target)) return target;
    const next = addDays(target, direction);
    if (compareISO(next, bounds.first) < 0 || compareISO(next, bounds.last) > 0) break;
    target = next;
  }
  return current;
}

/** The day that owns `tabindex="0"`: the requested one, else the first enabled cell. */
export function resolveFocus(
  rows: CalendarMatrix,
  focused: ISODate | null,
  blocked: (iso: ISODate) => boolean,
): ISODate | null {
  const cells = rows.flat();
  const wanted = cells.find((cell) => cell.iso === focused);
  if (wanted && !blocked(wanted.iso)) return wanted.iso;
  const fallback = cells.find((cell) => !blocked(cell.iso));
  return fallback ? fallback.iso : null;
}

/** Orders and validates the painted range; a single side paints one cell. */
function normalizeRange(range: PanelRange): { low: ISODate; high: ISODate } | null {
  const start = range.start !== undefined && isValidISO(range.start) ? range.start : '';
  const end = range.end !== undefined && isValidISO(range.end) ? range.end : '';
  if (start.length === 0 && end.length === 0) return null;
  if (start.length === 0) return { low: end, high: end };
  if (end.length === 0) return { low: start, high: start };
  return compareISO(start, end) <= 0 ? { low: start, high: end } : { low: end, high: start };
}

/** One day button, wrapped in its `gridcell`. */
function renderDay(
  cell: MatrixCell,
  options: CalendarPanelOptions,
  focus: ISODate | null,
  selected: ReadonlySet<string>,
  range: { low: ISODate; high: ISODate } | null,
  blocked: (iso: ISODate) => boolean,
): string {
  const { iso, inMonth } = cell;
  const parts = parseISO(iso);
  const classes = ['day'];
  const partNames = ['day'];
  if (!inMonth) {
    classes.push('day-outside');
    partNames.push('day-outside');
  }
  if (selected.has(iso)) {
    classes.push('day-selected');
    partNames.push('day-selected');
  }
  if (iso === options.today) {
    classes.push('day-today');
    partNames.push('day-today');
  }
  if (range !== null) {
    if (iso === range.low) classes.push('range-start');
    if (iso === range.high && range.high !== range.low) classes.push('range-end');
    if (compareISO(iso, range.low) > 0 && compareISO(iso, range.high) < 0) {
      classes.push('in-range');
    }
  }

  const disabled = blocked(iso);
  const label = parts === null
    ? iso
    : `${parts.year}年${parts.month}月${parts.day}日`;
  const attrs =
    ` data-iso="${iso}"` +
    ` tabindex="${iso === focus ? '0' : '-1'}"` +
    ` aria-label="${escapeHtml(label)}"` +
    (iso === options.today ? ' aria-current="date"' : '') +
    (disabled ? ' disabled aria-disabled="true"' : '');

  return (
    `<div class="cell" role="gridcell" aria-selected="${selected.has(iso) ? 'true' : 'false'}"` +
    `${disabled ? ' aria-disabled="true"' : ''}>` +
    `<button class="${classes.join(' ')}" part="${partNames.join(' ')}" type="button"${attrs}>` +
    `${parts === null ? '' : parts.day}` +
    `</button></div>`
  );
}

/**
 * Header, weekday row, 6 x 7 day grid and footer of one month.
 *
 * The result is the panel *body*: the owning component wraps it in its own
 * `part="panel"` element so it can toggle the popover and `hidden` state.
 */
export function renderCalendarPanel(options: CalendarPanelOptions): string {
  const blocked = (iso: ISODate): boolean =>
    isBlockedDay(iso, options.min, options.max, options.blocked);

  const rows = monthMatrix(options.year, options.month, options.firstDay);
  const focus = resolveFocus(rows, options.focused, blocked);
  const selected = new Set(options.selected);
  const range = options.range === null ? null : normalizeRange(options.range);
  const title = options.title ?? monthTitle(options.year, options.month);

  const weekdays =
    `<div class="row weekdays" role="row">` +
    weekdayLabels(options.firstDay)
      .map(
        (label) =>
          `<span class="weekday" part="weekday" role="columnheader"` +
          ` aria-label="周${label}">${label}</span>`,
      )
      .join('') +
    `</div>`;

  const gridRows = rows
    .map(
      (row) =>
        `<div class="row" role="row">${row
          .map((cell) => renderDay(cell, options, focus, selected, range, blocked))
          .join('')}</div>`,
    )
    .join('');

  const body =
    `<div class="header" part="header">` +
    `<button class="nav" part="nav-prev" data-focus="prev" type="button" aria-label="上个月">` +
    `<span aria-hidden="true">‹</span></button>` +
    `<div class="title" part="title" aria-live="polite">${escapeHtml(title)}</div>` +
    `<button class="nav" part="nav-next" data-focus="next" type="button" aria-label="下个月">` +
    `<span aria-hidden="true">›</span></button>` +
    `</div>` +
    `<div class="grid" part="grid" role="grid" aria-label="${escapeHtml(title)}">` +
    `${weekdays}${gridRows}` +
    `</div>` +
    `<div class="footer" part="footer">` +
    `<button class="footer-btn" part="clear" data-focus="clear" type="button"` +
    `${options.clear ? '' : ' disabled'}>清除</button>` +
    `<button class="footer-btn" part="today" data-focus="today" type="button"` +
    `${options.blocked ? ' disabled' : ''}>今天</button>` +
    `</div>`;

  return body;
}

/**
 * Anchored floating panel used by the overlay components (select, date picker,
 * combobox). Framework-free and dependency-free.
 *
 * The panel is promoted to the top layer through `popover="manual"` +
 * `showPopover()` when the platform supports it, and falls back to plain
 * `position: fixed` when it does not. Position is computed from
 * `getBoundingClientRect()` (viewport coordinates) with a vertical flip when the
 * space below the anchor is too small and a horizontal shift that keeps the
 * panel inside the viewport.
 */

/** Viewport margin that the horizontal shift keeps free on both sides. */
const VIEWPORT_MARGIN = 8;

/** Options accepted by `AnPopover`. */
export interface AnPopoverOptions {
  /** Element the panel is anchored to. */
  anchor: HTMLElement;
  /** Panel element that gets shown next to the anchor. */
  floating: HTMLElement;
  /** Keep the panel at least as wide as the anchor. Default: `true`. */
  matchWidth?: boolean;
  /** Gap between anchor and panel, in pixels. Default: `4`. */
  offset?: number;
  /** Called after a dismissal (outside pointerdown / Escape) closed the panel. */
  onClose?: () => void;
}

/** Inline styles `AnPopover` writes, so `close()` can put them back. */
interface SavedStyles {
  position: string;
  top: string;
  left: string;
  minWidth: string;
  inset: string;
  margin: string;
}

/**
 * Positions and dismisses one floating panel.
 *
 * `open()` / `close()` are idempotent; `close()` fires `onClose` only when the
 * panel actually was open, so a programmatic close and a dismissal notify the
 * owner the same way. `destroy()` tears the listeners and the popover state down
 * without notifying.
 */
export class AnPopover {
  #anchor: HTMLElement;
  #floating: HTMLElement;
  #matchWidth: boolean;
  #offset: number;
  #onClose?: () => void;
  #isOpen = false;
  /** Whether the panel currently sits in the top layer via the popover API. */
  #topLayer = false;
  /** `popover` attribute value found before `open()`, restored by `close()`. */
  #savedPopover: string | null = null;
  #savedStyles: SavedStyles | null = null;

  constructor(options: AnPopoverOptions) {
    this.#anchor = options.anchor;
    this.#floating = options.floating;
    this.#matchWidth = options.matchWidth ?? true;
    this.#offset = options.offset ?? 4;
    this.#onClose = options.onClose;
  }

  /** Whether the panel is currently shown. */
  get isOpen(): boolean {
    return this.#isOpen;
  }

  /** Shows the panel, positions it and starts tracking the viewport. */
  open(): void {
    if (this.#isOpen) return;
    this.#isOpen = true;
    this.#enterTopLayer();
    this.#captureStyles();
    this.reposition();
    this.#listen();
  }

  /** Hides the panel, stops tracking and notifies `onClose`. */
  close(): void {
    if (!this.#isOpen) return;
    this.#isOpen = false;
    this.#unlisten();
    this.#leaveTopLayer();
    this.#restoreStyles();
    this.#onClose?.();
  }

  /** Closes the panel when open, opens it otherwise. */
  toggle(): void {
    if (this.#isOpen) this.close();
    else this.open();
  }

  /** Recomputes the panel position from the current anchor rect. No-op closed. */
  reposition(): void {
    if (!this.#isOpen) return;
    const anchor = this.#anchor.getBoundingClientRect();
    const floating = this.#floating.getBoundingClientRect();
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
    const gap = this.#offset;
    const width = this.#matchWidth ? anchor.width : floating.width;
    const height = floating.height;

    // Below the anchor by default; flip above when it does not fit and there is
    // more room on the other side.
    let top = anchor.bottom + gap;
    const below = viewportHeight - anchor.bottom - gap;
    const above = anchor.top - gap;
    if (height > below && above > below) top = anchor.top - gap - height;

    // Keep both edges inside the viewport; a panel wider than the viewport
    // sticks to the left margin instead of going negative.
    const maxLeft = viewportWidth - VIEWPORT_MARGIN - width;
    const left = Math.min(
      Math.max(anchor.left, VIEWPORT_MARGIN),
      Math.max(maxLeft, VIEWPORT_MARGIN),
    );

    const style = this.#floating.style;
    style.top = `${Math.round(top)}px`;
    style.left = `${Math.round(left)}px`;
    if (this.#matchWidth) style.minWidth = `${Math.round(anchor.width)}px`;
  }

  /** Removes every listener, hides the panel and restores its inline styles. */
  destroy(): void {
    this.#isOpen = false;
    this.#unlisten();
    this.#leaveTopLayer();
    this.#restoreStyles();
  }

  /** Promotes the panel to the top layer when the popover API exists. */
  #enterTopLayer(): void {
    const floating = this.#floating;
    if (typeof floating.showPopover !== 'function') return;
    const previous = floating.getAttribute('popover');
    try {
      floating.setAttribute('popover', 'manual');
      floating.showPopover();
      this.#savedPopover = previous;
      this.#topLayer = true;
    } catch {
      // An implementation may expose the method but refuse to show (e.g. the
      // element is not connected): keep the attribute state untouched.
      if (previous === null) floating.removeAttribute('popover');
      else floating.setAttribute('popover', previous);
    }
  }

  /** Leaves the top layer and restores the `popover` attribute. */
  #leaveTopLayer(): void {
    if (this.#topLayer) {
      try {
        this.#floating.hidePopover();
      } catch {
        // Already hidden by the platform (e.g. a forced close).
      }
      const previous = this.#savedPopover;
      if (previous === null) this.#floating.removeAttribute('popover');
      else this.#floating.setAttribute('popover', previous);
    }
    this.#topLayer = false;
    this.#savedPopover = null;
  }

  /** Records the inline styles this class overrides and applies the overrides. */
  #captureStyles(): void {
    const style = this.#floating.style;
    this.#savedStyles = {
      position: style.position,
      top: style.top,
      left: style.left,
      minWidth: style.minWidth,
      inset: style.inset,
      margin: style.margin,
    };
    style.position = 'fixed';
    style.inset = 'auto';
    style.margin = '0';
  }

  /** Restores the inline styles captured by `#captureStyles()`. */
  #restoreStyles(): void {
    const saved = this.#savedStyles;
    this.#savedStyles = null;
    if (!saved) return;
    const style = this.#floating.style;
    style.position = saved.position;
    style.top = saved.top;
    style.left = saved.left;
    style.minWidth = saved.minWidth;
    style.inset = saved.inset;
    style.margin = saved.margin;
  }

  #listen(): void {
    // `capture: true` also sees scrolls that happen in inner scroll containers.
    document.addEventListener('scroll', this.#onScroll, { capture: true, passive: true });
    window.addEventListener('resize', this.#onResize);
    document.addEventListener('pointerdown', this.#onPointerDown, true);
    document.addEventListener('keydown', this.#onKeyDown, true);
  }

  #unlisten(): void {
    document.removeEventListener('scroll', this.#onScroll, true);
    window.removeEventListener('resize', this.#onResize);
    document.removeEventListener('pointerdown', this.#onPointerDown, true);
    document.removeEventListener('keydown', this.#onKeyDown, true);
  }

  #onScroll = (): void => {
    this.reposition();
  };

  #onResize = (): void => {
    this.reposition();
  };

  /**
   * Closes on a pointerdown outside both the anchor and the panel. The composed
   * path is used first so a target inside a shadow tree still counts as inside.
   */
  #onPointerDown = (event: Event): void => {
    if (!this.#isOpen) return;
    const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
    if (path.includes(this.#anchor) || path.includes(this.#floating)) return;
    if (path.length === 0) {
      const target = event.target;
      if (target instanceof Node && (this.#anchor.contains(target) || this.#floating.contains(target))) {
        return;
      }
    }
    this.close();
  };

  #onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Escape') return;
    this.close();
  };
}

/**
 * Composition helper shared by `<an-date>` and `<an-date-range>`.
 *
 * The two elements must each literally `extends AnElement` (the build and the
 * CEM scanner derive the tag name from that declaration), so the shared
 * calendar machinery lives in this plain controller class instead of a common
 * base element. Each component creates one controller in its constructor and
 * forwards the lifecycle hooks, attributes and render slots to it:
 *
 * ```ts
 * this.#panel = new DatePanelController(this.#host());
 * ```
 *
 * The controller owns the month view, the popover (`AnPopover`), the
 * roving-focus keyboard model, the controlled `open` state and the focus/scroll
 * restoration that the `innerHTML` re-render would otherwise destroy. It never
 * extends `AnElement` and never registers a custom element.
 */

import { AnPopover } from '../internal/popover';
import {
  ISODate,
  addMonths,
  compareISO,
  isValidISO,
  monthMatrix,
  parseISO,
  todayISO,
} from '../internal/calendar';
import {
  CalendarMatrix,
  PanelRange,
  escapeHtml,
  gridBounds,
  isBlockedDay,
  nearestEnabled,
  renderCalendarPanel,
  stepFocus,
  weekEnd,
  weekStart,
} from './calendar-panel';

/** Attributes every date control declares; a component spreads this into `defaults`. */
export const SHARED_DEFAULTS = {
  disabled: false,
  firstDay: 1,
  inline: false,
  max: '',
  min: '',
  name: '',
  open: false,
  placeholder: '',
  required: false,
  size: 'md',
} as const;

/** Everything `DatePanelController` needs from the element that owns it. */
export interface DateHost {
  /** The component instance; the controller reads attributes and the shadow root. */
  readonly element: HTMLElement;
  readonly inline: boolean;
  readonly disabled: boolean;
  /** `true` when no day may be picked (disabled, form-disabled or readonly). */
  readonly blocked: boolean;
  readonly formDisabled: boolean;
  readonly firstDay: number;
  readonly min: string;
  readonly max: string;
  /** Controlled open state; the controller forces it back to `false` when unusable. */
  readonly open: boolean;
  /** Endpoints painted as selected. */
  readonly selectedDays: readonly ISODate[];
  /** Range painted behind the days; `null` in `<an-date>`. */
  readonly rangePreview: PanelRange | null;
  readonly canClear: boolean;
  /** Text shown inside the trigger input. */
  readonly displayText: string;
  readonly placeholder: string;
  readonly inputReadonly: boolean;
  /** Fallback accessible name of the trigger. */
  readonly accessibleName: string;
  /** Accessible name of the dialog. */
  readonly panelLabel: string;
  /** Prefix of the emitted events (`an-date`, `an-date-range`). */
  readonly eventPrefix: string;
  /** Whether opening/closing the panel emits its own events. */
  readonly emitPanelEvents: boolean;
  /** Opens the panel through the component so its guard keeps working. */
  show(): void;
  /** Closes the panel by clearing the controlled state. */
  close(): void;
  /** Writes the controlled state straight from the controller. */
  setOpen(next: boolean): void;
  /** Emits `<eventPrefix>-open` / `-close` with the component's `emit`. */
  emitPanelEvent(name: string): void;
  /** Handles a day picked by click, Enter or the footer "今天" button. */
  commitDay(iso: ISODate, originalEvent: Event): void;
  /** Handles the footer "清除" button. */
  clearSelection(originalEvent: Event): void;
  /** Commits the text typed into the trigger (blur / Enter). */
  commitInput(raw: string, originalEvent: Event): void;
  /** A day cell was hovered; `''` means the pointer left the grid. */
  onDayHover(iso: ISODate): void;
  /** Re-renders the owning element. */
  requestUpdate(): void;
  /**
   * Markup for the shortcut rail rendered at the bottom of the panel; omit it
   * (or return `''`) when the control has no presets.
   */
  renderPresets?(): string;
  /**
   * Applies preset `index`; returns the day the calendar should show, or
   * `undefined` when the preset is out of range / the control is blocked.
   */
  applyPreset?(index: number): ISODate | undefined;
}

/** Day-cell key used by the focus-restore map: `iso:2026-11-19`. */
const ISO_PREFIX = 'iso:';

let nextPanelId = 0;

/**
 * `ShadowRoot#activeElement` walks the host chain and can throw while the tree
 * is detached (e.g. after the element was removed mid-interaction); treat that
 * as "no focus inside the control".
 */
function shadowActiveElement(root: ShadowRoot | null | undefined): HTMLElement | null {
  if (root === null || root === undefined) return null;
  try {
    return (root.activeElement as HTMLElement | null) ?? null;
  } catch {
    return null;
  }
}

/** Inline calendar icon; decorative, the input carries the accessible name. */
const CALENDAR_ICON =
  '<svg viewBox="0 0 24 24" aria-hidden="true">' +
  '<rect x="3" y="5" width="18" height="16" rx="2"></rect>' +
  '<path d="M8 3v4M16 3v4M3 10h18"></path>' +
  '</svg>';

/**
 * Calendar state and behaviour shared by the two date controls.
 *
 * Composition, not inheritance: the controller is a plain class, so the
 * components keep the literal `export class AnDate extends AnElement` shape the
 * build and CEM scanners require.
 */
export class DatePanelController {
  #host: DateHost;
  #panelId: string;
  #viewYear = 1970;
  #viewMonth = 1;
  /** Roving-focus day; always a valid `YYYY-MM-DD` once `connect()` ran. */
  #focusedISO = '';
  #panelOpen = false;
  #popover: AnPopover | null = null;
  #savedFocus: string | null = null;
  #pendingFocus: string | null = null;
  #savedScrollTop = 0;
  #hasLabel = false;
  #syncingOpen = false;
  /** `open` resolved to `true` after the last sync, so the view resets only once. */
  #wasOpen = false;

  constructor(host: DateHost) {
    this.#host = host;
    this.#panelId = `an-date-panel-${++nextPanelId}`;
  }

  /** Installs the delegated listeners on the shadow root; call after `super()`. */
  listen(): void {
    const root = this.#shadow();
    if (root === null) return;
    root.addEventListener('click', this.#onClick);
    root.addEventListener('keydown', this.#onKeyDown);
    root.addEventListener('focusout', this.#onFocusOut);
    root.addEventListener('pointerover', this.#onPointerOver);
    root.addEventListener('pointerout', this.#onPointerOut);
    root.addEventListener('slotchange', this.#onSlotChange);
  }

  /** Hooks the controller into the element lifecycle (`onConnect`). */
  connect(): void {
    this.#wasOpen = false;
    this.#focusedISO = this.#focusAnchor();
    this.#syncView(this.#focusedISO);
    // `connectedCallback()` renders before this hook runs, so the first paint
    // would show the initial 1970 view; sync it with the real month.
    this.#syncOpenState();
  }

  /** Releases the popover listeners while the element is out of the document. */
  disconnect(): void {
    this.#popover?.destroy();
    this.#popover = null;
    this.#panelOpen = false;
  }

  /** Popover lifecycle and focus restoration; call from `afterRender()`. */
  afterRender(): void {
    this.#syncPopover();
    this.#restoreFocus();
  }

  /** Remembers focus and scroll before `AnElement` replaces the shadow DOM. */
  captureFocus(): void {
    const active = shadowActiveElement(this.#shadow());
    this.#savedFocus =
      active === null
        ? null
        : active.dataset.iso !== undefined
          ? `${ISO_PREFIX}${active.dataset.iso}`
          : active.dataset.focus ?? null;
    this.#savedScrollTop = this.#panel()?.scrollTop ?? 0;
  }

  /** Reacts to reflected attributes the controller owns. */
  attributeChanged(name: string, oldValue: string | null, value: string | null): void {
    if (name === 'open') {
      if (this.#syncingOpen || oldValue === value) return;
      this.#syncOpenState();
      return;
    }
    if (name === 'disabled' || name === 'inline') this.#syncBlockedState();
  }

  /** Closes an open panel after `blocked` changed through a component-owned attribute. */
  blockedChanged(): void {
    this.#syncBlockedState();
  }

  /** Focuses the trigger text field after a close. */
  focusTrigger(): void {
    const input = this.#input();
    if (input !== null) input.focus();
  }

  // -------------------------------------------------------------------------
  // Rendering
  // -------------------------------------------------------------------------

  /** Label slot wrapper; hidden until the light DOM fills it. */
  renderLabel(): string {
    return (
      `<span class="label" part="label"${this.#hasLabel ? '' : ' hidden'}>` +
      `<slot name="label"></slot></span>`
    );
  }

  /** Trigger markup; the component omits it in `inline` mode. */
  renderTrigger(): string {
    const host = this.#host;
    const display = host.displayText;
    const nameAttribute = this.#accessibleNameAttribute();
    const inactive = host.disabled || host.formDisabled;
    return (
      `<div class="trigger" part="trigger" data-trigger=""` +
      `${inactive ? ' data-disabled=""' : ''}>` +
      `<input class="input" part="input" data-focus="input" type="text" role="combobox"` +
      ` autocomplete="off" spellcheck="false" aria-haspopup="dialog"` +
      ` aria-expanded="${host.open ? 'true' : 'false'}" aria-controls="${this.#panelId}"` +
      `${nameAttribute}` +
      ` placeholder="${escapeHtml(host.placeholder)}"` +
      (display.length > 0 ? ` value="${escapeHtml(display)}"` : '') +
      (inactive ? ' disabled' : '') +
      (host.inputReadonly ? ' readonly' : '') +
      `>` +
      `<span class="icon">${CALENDAR_ICON}</span>` +
      `</div>`
    );
  }

  /** Panel wrapper plus the month grid. */
  renderPanel(): string {
    const host = this.#host;
    const hidden = !host.inline && !host.open;
    const body = renderCalendarPanel({
      year: this.#viewYear,
      month: this.#viewMonth,
      firstDay: host.firstDay === 0 ? 0 : 1,
      selected: host.selectedDays,
      range: host.rangePreview,
      focused: this.#focusedISO === '' ? null : this.#focusedISO,
      min: this.#minISO,
      max: this.#maxISO,
      today: todayISO(),
      blocked: host.blocked,
      clear: host.canClear,
    });
    return (
      `<div class="panel" part="panel" role="dialog" id="${this.#panelId}" aria-modal="false"` +
      ` aria-label="${escapeHtml(host.panelLabel)}"${hidden ? ' hidden' : ''}>` +
      body +
      (host.renderPresets?.() ?? '') +
      `</div>`
    );
  }

  #accessibleNameAttribute(): string {
    const element = this.#host.element;
    const label = element.getAttribute('aria-label');
    if (label !== null && label.length > 0) return ` aria-label="${escapeHtml(label)}"`;
    const labelledBy = element.getAttribute('aria-labelledby');
    if (labelledBy !== null && labelledBy.length > 0) {
      return ` aria-labelledby="${escapeHtml(labelledBy)}"`;
    }
    return ` aria-label="${escapeHtml(this.#host.accessibleName)}"`;
  }

  // -------------------------------------------------------------------------
  // Open / close
  // -------------------------------------------------------------------------

  /** Writes the controlled state without re-entering the attribute handler. */
  #writeOpen(next: boolean): void {
    if (this.#host.open === next) return;
    this.#syncingOpen = true;
    try {
      this.#host.setOpen(next);
    } finally {
      this.#syncingOpen = false;
    }
  }

  /**
   * Resolves the controlled `open` state: forces it off where the panel cannot
   * exist (`inline`, `disabled`, `readonly`), starts the view on the selection
   * the first time it opens and re-renders so `afterRender()` can recreate the
   * popover.
   */
  #syncOpenState(): void {
    const host = this.#host;
    const wanted = host.open && !host.inline && !host.blocked;
    if (wanted !== host.open) {
      this.#writeOpen(wanted);
      this.#wasOpen = false;
      this.#pendingFocus = null;
      return;
    }
    if (wanted && !this.#wasOpen) {
      this.#focusedISO = this.#focusAnchor();
      this.#syncView(this.#focusedISO);
    }
    if (!wanted) this.#pendingFocus = null;
    this.#wasOpen = wanted;
    host.requestUpdate();
  }

  #syncBlockedState(): void {
    if (this.#host.blocked || this.#host.inline) this.#writeOpen(false);
  }

  #onPopoverClose = (): void => {
    if (!this.#host.open) return;
    // A keyboard dismissal leaves focus on a day button that is about to be
    // re-rendered away; an outside click already moved focus by itself.
    const focusWasInside = shadowActiveElement(this.#shadow()) !== null;
    this.#host.close();
    if (focusWasInside) this.focusTrigger();
  };

  #syncPopover(): void {
    const host = this.#host;
    const panel = this.#panel();
    if (host.inline || !host.open) {
      this.#popover?.destroy();
      this.#popover = null;
      if (this.#panelOpen) {
        this.#panelOpen = false;
        if (host.emitPanelEvents) host.emitPanelEvent(`${host.eventPrefix}-close`);
      }
      return;
    }
    const anchor = this.#shadow()?.querySelector<HTMLElement>('[part~="trigger"]') ?? null;
    if (panel === null || anchor === null) return;
    this.#popover?.destroy();
    this.#popover = new AnPopover({
      anchor,
      floating: panel,
      offset: 4,
      matchWidth: true,
      onClose: this.#onPopoverClose,
    });
    this.#popover.open();
    if (!this.#panelOpen) {
      this.#panelOpen = true;
      if (host.emitPanelEvents) host.emitPanelEvent(`${host.eventPrefix}-open`);
    }
  }

  #syncView(iso: ISODate): void {
    const parts = parseISO(iso);
    if (parts === null) return;
    this.#viewYear = parts.year;
    this.#viewMonth = parts.month;
  }

  // -------------------------------------------------------------------------
  // Focus restore
  // -------------------------------------------------------------------------

  #restoreFocus(): void {
    const panel = this.#panel();
    if (panel !== null) panel.scrollTop = this.#savedScrollTop;
    const pending = this.#pendingFocus;
    const saved = this.#savedFocus;
    this.#pendingFocus = null;
    this.#savedFocus = null;
    if (!this.#host.open && !this.#host.inline) return;
    if (pending !== null && this.#focusByKey(pending)) return;
    if (saved !== null) this.#focusByKey(saved);
  }

  #focusByKey(key: string): boolean {
    if (key.startsWith(ISO_PREFIX)) return this.#focusDayButton(key.slice(ISO_PREFIX.length));
    if (!/^[a-z]+$/.test(key)) return false;
    const target = this.#shadow()?.querySelector<HTMLElement>(`[data-focus="${key}"]`) ?? null;
    if (target === null || target.hasAttribute('disabled') || target.closest('[hidden]') !== null) {
      return false;
    }
    target.focus();
    return true;
  }

  #focusDayButton(iso: string): boolean {
    const button = this.#dayButton(iso);
    if (button === null || button.disabled) return false;
    button.focus();
    return true;
  }

  // -------------------------------------------------------------------------
  // Interaction
  // -------------------------------------------------------------------------

  #onClick = (event: Event): void => {
    const target = event.target as Element | null;
    if (target === null) return;

    const day = target.closest('[data-iso]');
    if (day !== null) {
      this.#clickDay(day as HTMLElement, event);
      return;
    }

    const trigger = target.closest('[data-trigger]');
    if (trigger !== null) {
      this.focusTrigger();
      this.#host.show();
      return;
    }

    // Shortcut buttons belong to the owning element (only `<an-date-range>` has
    // them); the controller only moves the visible month to the new range.
    const preset = target.closest('[data-preset-index]') as HTMLElement | null;
    if (preset !== null) {
      const index = Number(preset.dataset.presetIndex);
      if (!Number.isInteger(index)) return;
      const focusISO = this.#host.applyPreset?.(index);
      if (focusISO !== undefined && isValidISO(focusISO)) {
        this.#focusedISO = focusISO;
        this.#syncView(focusISO);
      }
      return;
    }

    const action = target.closest('[data-focus]') as HTMLElement | null;
    if (action === null) return;
    switch (action.dataset.focus) {
      case 'prev':
        this.#stepMonth(-1, false);
        break;
      case 'next':
        this.#stepMonth(1, false);
        break;
      case 'clear':
        if (!this.#host.blocked) this.#host.clearSelection(event);
        break;
      case 'today':
        this.#pickToday(event);
        break;
      default:
        break;
    }
  };

  #clickDay(day: HTMLElement, event: Event): void {
    if (this.#host.blocked) return;
    const iso = day.dataset.iso ?? '';
    if (!isValidISO(iso) || this.#isBlocked(iso)) return;
    this.#focusedISO = iso;
    this.#host.commitDay(iso, event);
  }

  #pickToday(event: Event): void {
    const today = todayISO();
    if (this.#host.blocked || this.#isBlocked(today)) return;
    this.#focusedISO = today;
    this.#syncView(today);
    this.#host.commitDay(today, event);
  }

  #onKeyDown = (event: Event): void => {
    const keyboard = event as KeyboardEvent;
    const host = this.#host;
    const target = event.target as HTMLElement | null;
    const iso = target?.dataset.iso ?? '';
    const onInput = target?.dataset.focus === 'input';

    if (keyboard.key === 'Escape') {
      if (host.inline) return;
      if (host.open) {
        event.preventDefault();
        host.close();
        this.focusTrigger();
      }
      return;
    }

    if (onInput) {
      if (host.blocked) return;
      if (keyboard.key === 'ArrowDown' || keyboard.key === 'ArrowUp') {
        event.preventDefault();
        if (!host.open) host.show();
        this.#focusIntoGrid();
        return;
      }
      if (keyboard.key === 'Enter') {
        host.commitInput((target as HTMLInputElement).value, event);
      }
      return;
    }

    if (iso.length === 0 || host.blocked) return;

    switch (keyboard.key) {
      case 'ArrowLeft':
        this.#moveFocus(-1);
        break;
      case 'ArrowRight':
        this.#moveFocus(1);
        break;
      case 'ArrowUp':
        this.#moveFocus(-7);
        break;
      case 'ArrowDown':
        this.#moveFocus(7);
        break;
      case 'PageUp':
        this.#stepMonth(-1, true);
        break;
      case 'PageDown':
        this.#stepMonth(1, true);
        break;
      case 'Home':
        this.#focusWeekEdge(false);
        break;
      case 'End':
        this.#focusWeekEdge(true);
        break;
      case 'Enter':
      case ' ':
        host.commitDay(iso, event);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  /** Moves real focus into the grid, e.g. from ArrowDown on the trigger. */
  #focusIntoGrid(): void {
    const matrix = this.#matrix();
    const bounds = gridBounds(matrix);
    let target = this.#focusedISO === '' ? this.#focusAnchor() : this.#focusedISO;
    if (compareISO(target, bounds.first) < 0) target = bounds.first;
    if (compareISO(target, bounds.last) > 0) target = bounds.last;
    const next = nearestEnabled(target, bounds, (iso: ISODate): boolean => this.#isBlocked(iso));
    this.#focusedISO = next;
    this.#syncView(next);
    this.#pendingFocus = `${ISO_PREFIX}${next}`;
    this.#host.requestUpdate();
  }

  #moveFocus(delta: number): void {
    const matrix = this.#matrix();
    const bounds = gridBounds(matrix);
    const current = this.#focusedISO === '' ? bounds.first : this.#focusedISO;
    const next = stepFocus(current, delta, bounds, (iso: ISODate): boolean => this.#isBlocked(iso));
    this.#focusedISO = next;
    this.#pendingFocus = `${ISO_PREFIX}${next}`;
    this.#host.requestUpdate();
  }

  #focusWeekEdge(end: boolean): void {
    const matrix = this.#matrix();
    const bounds = gridBounds(matrix);
    const firstDay = this.#host.firstDay === 0 ? 0 : 1;
    const current = this.#focusedISO === '' ? bounds.first : this.#focusedISO;
    let target = end ? weekEnd(current, firstDay) : weekStart(current, firstDay);
    if (compareISO(target, bounds.first) < 0) target = bounds.first;
    if (compareISO(target, bounds.last) > 0) target = bounds.last;
    const next = nearestEnabled(target, bounds, (iso: ISODate): boolean => this.#isBlocked(iso));
    this.#focusedISO = next;
    this.#pendingFocus = `${ISO_PREFIX}${next}`;
    this.#host.requestUpdate();
  }

  #stepMonth(delta: number, focusDayButton: boolean): void {
    const view = addMonths({ year: this.#viewYear, month: this.#viewMonth }, delta);
    const matrix = monthMatrix(view.year, view.month, this.#host.firstDay === 0 ? 0 : 1);
    const bounds = gridBounds(matrix);
    const focused = parseISO(this.#focusedISO === '' ? this.#viewMonthISO() : this.#focusedISO);
    const day = focused === null ? 1 : focused.day;
    const inMonth = matrix.flat().filter((cell) => cell.inMonth);
    const index = Math.min(day, inMonth.length) - 1;
    const wanted = inMonth[index < 0 ? 0 : index].iso;
    const next = nearestEnabled(wanted, bounds, (iso: ISODate): boolean => this.#isBlocked(iso));
    this.#viewYear = view.year;
    this.#viewMonth = view.month;
    this.#focusedISO = next;
    if (focusDayButton) this.#pendingFocus = `${ISO_PREFIX}${next}`;
    this.#host.requestUpdate();
  }

  #onFocusOut = (event: Event): void => {
    const focusEvent = event as FocusEvent;
    const target = event.target as HTMLElement | null;
    if (target?.dataset.focus !== 'input') return;
    const related = focusEvent.relatedTarget as Node | null;
    if (related !== null && this.#shadow()?.contains(related) === true) return;
    const input = this.#input();
    if (input === null) return;
    this.#host.commitInput(input.value, event);
  };

  #onPointerOver = (event: Event): void => {
    const target = (event.target as Element | null)?.closest('[data-iso]') as HTMLElement | null;
    if (target === null) return;
    this.#host.onDayHover(target.dataset.iso ?? '');
  };

  #onPointerOut = (event: Event): void => {
    const related = (event as PointerEvent).relatedTarget as Element | null;
    if (related !== null) {
      const grid = this.#shadow()?.querySelector('[part~="grid"]') ?? null;
      if (grid !== null && grid.contains(related)) return;
    }
    this.#host.onDayHover('');
  };

  #onSlotChange = (event: Event): void => {
    const slot = event.target as HTMLSlotElement;
    const has = slot
      .assignedNodes({ flatten: true })
      .some((node) => (node.textContent ?? '').trim().length > 0);
    if (has === this.#hasLabel) return;
    this.#hasLabel = has;
    this.#host.requestUpdate();
  };

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------

  #shadow(): ShadowRoot | null {
    return this.#host.element.shadowRoot;
  }

  #focusAnchor(): ISODate {
    const [first] = this.#host.selectedDays;
    return first !== undefined && isValidISO(first) ? first : todayISO();
  }

  #viewMonthISO(): ISODate {
    const month = String(this.#viewMonth).padStart(2, '0');
    return `${this.#viewYear}-${month}-01`;
  }

  #matrix(): CalendarMatrix {
    return monthMatrix(this.#viewYear, this.#viewMonth, this.#host.firstDay === 0 ? 0 : 1);
  }

  #isBlocked(iso: ISODate): boolean {
    return isBlockedDay(iso, this.#minISO, this.#maxISO, this.#host.blocked);
  }

  get #minISO(): ISODate | undefined {
    const { min } = this.#host;
    return isValidISO(min) ? min : undefined;
  }

  get #maxISO(): ISODate | undefined {
    const { max } = this.#host;
    return isValidISO(max) ? max : undefined;
  }

  #panel(): HTMLElement | null {
    return this.#shadow()?.querySelector<HTMLElement>('[part~="panel"]') ?? null;
  }

  #input(): HTMLInputElement | null {
    return (
      this.#shadow()?.querySelector<HTMLInputElement>('input[data-focus="input"]') ?? null
    );
  }

  #dayButton(iso: ISODate): HTMLButtonElement | null {
    return (
      this.#shadow()?.querySelector<HTMLButtonElement>(`button[data-iso="${iso}"]`) ?? null
    );
  }
}

/* Hooks: --an-date-height | --an-date-bg | --an-date-fg | --an-date-border-color
   | --an-date-radius | --an-date-font-size | --an-date-padding-x | --an-date-focus-ring
   | --an-date-muted-fg | --an-date-panel-bg | --an-date-panel-fg
   | --an-date-panel-border-color | --an-date-panel-radius | --an-date-panel-shadow
   | --an-date-day-size | --an-date-day-hover-bg | --an-date-day-selected-bg
   | --an-date-day-selected-fg | --an-date-range-bg | --an-date-today-ring.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  box-sizing: border-box;
  border: 0 solid transparent;
  margin: 0;
  line-height: 1.5;

  display: inline-block;
  vertical-align: middle;
  color-scheme: light dark;
  font: inherit;
  color: var(--an-color-fg-1, #1f2937);
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :host(:not([data-theme='light'])) {
    color-scheme: dark;
  }
}

.trigger {
  min-width: 11rem;
}

:host([inline]) {
  display: inline-flex;
}

:host([inline]) .base {
  width: auto;
}

/* Shared calendar surface for <an-date> and <an-date-range>.
   Hooks: --an-date-height | --an-date-bg | --an-date-fg | --an-date-border-color
   | --an-date-radius | --an-date-font-size | --an-date-padding-x | --an-date-focus-ring
   | --an-date-muted-fg | --an-date-panel-bg | --an-date-panel-fg
   | --an-date-panel-border-color | --an-date-panel-radius | --an-date-panel-shadow
   | --an-date-day-size | --an-date-day-hover-bg | --an-date-day-selected-bg
   | --an-date-day-selected-fg | --an-date-range-bg | --an-date-today-ring.
   `<an-date-range>` maps every hook from its own `--an-date-range-*` prefix.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

.base {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  font-family: inherit;
}

.label {
  color: var(--an-color-fg-1, #1f2937);
  font-size: var(--an-font-size-sm, 0.875rem);
  font-weight: 500;
}

.label[hidden] {
  display: none;
}

.trigger {
  display: flex;
  align-items: center;
  gap: var(--an-space-2, 0.5rem);
  box-sizing: border-box;
  height: var(--an-date-height, var(--an-space-11, 2.75rem));
  padding: 0 var(--an-date-padding-x, var(--an-space-3, 0.75rem));
  border: 1px solid var(--an-date-border-color, var(--an-color-border-1, #d1d5db));
  border-radius: var(--an-date-radius, var(--an-radius-md, 0.5rem));
  background: var(--an-date-bg, var(--an-color-bg-1, #ffffff));
  color: var(--an-date-fg, var(--an-color-fg-1, #1f2937));
  font-size: var(--an-date-font-size, var(--an-font-size-md, 1rem));
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.trigger:focus-within {
  border-color: var(--an-color-accent-9, #2563eb);
  box-shadow: 0 0 0 3px var(--an-date-focus-ring, rgb(37 99 235 / 0.25));
}

.trigger[data-disabled] {
  cursor: not-allowed;
  opacity: 0.6;
}

.input {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  line-height: inherit;
  outline: none;
}

.input::placeholder {
  color: var(--an-date-muted-fg, var(--an-color-gray-8, #9ca3af));
}

.input:disabled {
  cursor: not-allowed;
}

.icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  color: var(--an-date-muted-fg, var(--an-color-gray-9, #6b7280));
  pointer-events: none;
}

.icon svg {
  display: block;
  width: 1.125em;
  height: 1.125em;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
}

.panel {
  box-sizing: border-box;
  width: 17.5rem;
  padding: var(--an-space-3, 0.75rem);
  border: 1px solid var(--an-date-panel-border-color, var(--an-color-border-1, #e5e7eb));
  border-radius: var(--an-date-panel-radius, var(--an-radius-lg, 0.625rem));
  background: var(--an-date-panel-bg, var(--an-color-bg-1, #ffffff));
  color: var(--an-date-panel-fg, var(--an-color-fg-1, #1f2937));
  box-shadow: var(--an-date-panel-shadow, 0 12px 32px rgb(15 23 42 / 0.18));
  font-family: inherit;
  font-size: var(--an-date-font-size, var(--an-font-size-md, 1rem));
}

/* Floating mode: the popover writes top/left inline; inline mode sits in flow. */
:host(:not([inline])) .panel {
  position: fixed;
  z-index: 1000;
  inset: auto;
  margin: 0;
}

:host([inline]) .panel {
  position: static;
  width: auto;
  box-shadow: none;
}

.panel[hidden] {
  display: none;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--an-space-2, 0.5rem);
  margin-bottom: var(--an-space-2, 0.5rem);
}

.title {
  flex: 1 1 auto;
  color: var(--an-date-panel-fg, var(--an-color-fg-1, #1f2937));
  font-size: var(--an-font-size-sm, 0.875rem);
  font-weight: 600;
  text-align: center;
}

.nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--an-radius-md, 0.5rem);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 1.125rem;
  line-height: 1;
  cursor: pointer;
}

.nav:hover:not(:disabled) {
  background: var(--an-color-gray-2, #f3f4f6);
}

.nav:focus-visible {
  outline: 2px solid var(--an-color-accent-9, #2563eb);
  outline-offset: 2px;
}

.nav:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.grid {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}

.weekdays {
  margin-bottom: 2px;
}

.weekday {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 1.75rem;
  color: var(--an-date-muted-fg, var(--an-color-gray-9, #6b7280));
  font-size: var(--an-font-size-xs, 0.75rem);
  font-weight: 500;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: center;
}

.day {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--an-date-day-size, 2.25rem);
  height: var(--an-date-day-size, 2.25rem);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--an-radius-full, 9999px);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1;
  cursor: pointer;
}

.day:hover:not(:disabled) {
  background: var(--an-date-day-hover-bg, var(--an-color-gray-2, #f3f4f6));
}

.day:focus-visible {
  outline: 2px solid var(--an-color-accent-9, #2563eb);
  outline-offset: 2px;
}

.day.day-today {
  box-shadow: inset 0 0 0 1px var(--an-date-today-ring, var(--an-color-accent-9, #2563eb));
}

.day.day-outside {
  color: var(
    --an-date-muted-fg,
    color-mix(in srgb, var(--an-color-fg-1, #626262) 68%, var(--an-color-bg-1, #626262))
  );
}

/* Range hosts map muted-fg to gray-9, which is too faint for active day text. */
:host(an-date-range) .day.day-outside:not(:disabled):not(.day-selected) {
  color: var(
    --an-date-range-muted-fg,
    color-mix(in srgb, var(--an-color-fg-1, #626262) 68%, var(--an-color-bg-1, #626262))
  );
}

.day.day-selected {
  background: var(--an-date-day-selected-bg, var(--an-color-accent-9, #2563eb));
  color: var(--an-date-day-selected-fg, #ffffff);
}

.day.in-range {
  border-radius: 0;
  background: var(--an-date-range-bg, var(--an-color-gray-3, #e5e7eb));
}

.day.range-start:not(.day-selected),
.day.range-end:not(.day-selected) {
  background: var(--an-date-range-bg, var(--an-color-gray-3, #e5e7eb));
}

.day:disabled {
  color: var(--an-date-muted-fg, var(--an-color-gray-7, #9ca3af));
  cursor: not-allowed;
  opacity: 0.55;
}

.day:disabled:hover {
  background: transparent;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--an-space-2, 0.5rem);
  margin-top: var(--an-space-2, 0.5rem);
  padding-top: var(--an-space-2, 0.5rem);
  border-top: 1px solid var(--an-date-panel-border-color, var(--an-color-border-1, #e5e7eb));
}

.footer-btn {
  margin: 0;
  padding: 0.25rem 0.375rem;
  border: 0;
  border-radius: var(--an-radius-sm, 0.375rem);
  background: transparent;
  color: var(--an-color-accent-9, #2563eb);
  font: inherit;
  font-size: var(--an-font-size-sm, 0.875rem);
  cursor: pointer;
}

.footer-btn:hover:not(:disabled) {
  background: var(--an-color-gray-2, #f3f4f6);
}

/* Semantic tokens carry the theme through shadow hosts such as <an-field>. */
@container style(--an-color-bg-1: var(--an-color-gray-12)) {
  .footer-btn:not(:disabled) {
    color: color-mix(
      in srgb,
      var(--an-color-accent-9, #2563eb) 72%,
      var(--an-date-panel-fg, var(--an-color-fg-1, #f9fafb))
    );
  }

  .footer-btn:hover:not(:disabled) {
    background: color-mix(
      in srgb,
      var(--an-date-panel-bg, var(--an-color-bg-1, #111827)) 88%,
      var(--an-date-panel-fg, var(--an-color-fg-1, #f9fafb))
    );
  }
}

.footer-btn:focus-visible {
  outline: 2px solid var(--an-color-accent-9, #2563eb);
  outline-offset: 2px;
}

.footer-btn:disabled {
  color: var(--an-date-muted-fg, var(--an-color-gray-8, #9ca3af));
  cursor: not-allowed;
}

/* Size scale. */
:host([size='sm']) .trigger {
  height: var(--an-date-height, var(--an-space-9, 2.25rem));
  font-size: var(--an-date-font-size, var(--an-font-size-sm, 0.875rem));
}

:host([size='lg']) .trigger {
  height: var(--an-date-height, var(--an-space-12, 3rem));
  font-size: var(--an-date-font-size, var(--an-font-size-lg, 1.125rem));
}

import { AnElement } from '../internal/base';
import { ISODate, compareISO, isValidISO } from '../internal/calendar';
import { formatDisplay } from './calendar-panel';
import { DateHost, DatePanelController, SHARED_DEFAULTS } from './date-base';
import dateStyles from './an-date.css?inline';
import panelStyles from './panel.css?inline';

/** Control sizes of `<an-date>`. */
export type AnDateSize = 'sm' | 'md' | 'lg';

/** Allowed `size` values; unknown attributes fall back to `md` through CSS. */
const SIZES: readonly AnDateSize[] = ['sm', 'md', 'lg'];

/** Shown to the owning form when `required` is set and nothing is selected. */
const REQUIRED_MESSAGE = '此字段为必填项。';

/** Payload of `an-date-change`. */
export interface AnDateChangeDetail {
  /** Selected day in `YYYY-MM-DD`, `''` when cleared. */
  value: ISODate;
  /** Event that caused the change (click, change, keydown or blur). */
  originalEvent: Event;
}

/**
 * `<an-date>` — a form-associated single-date picker.
 *
 * ```html
 * <an-date name="day" value="2026-11-19" min="2026-01-01" max="2026-12-31"></an-date>
 * ```
 *
 * The class extends `AnElement` directly (the build and CEM scanners derive the
 * tag name from that literal declaration); the shared calendar machinery lives
 * in `DatePanelController`, composed in the constructor.
 *
 * @attr value - Selected day in `YYYY-MM-DD`; seeds the property, never written back.
 * @attr min - Earliest selectable day in `YYYY-MM-DD`.
 * @attr max - Latest selectable day in `YYYY-MM-DD`.
 * @attr open - Controlled open state of the panel; reflect target of the `open` property.
 * @attr inline - Keeps the panel in flow and removes the trigger.
 * @attr disabled - Blocks every interaction and submission.
 * @attr readonly - Shows the value but forbids picking or typing.
 * @attr required - Reports `valueMissing` while no day is selected.
 * @attr placeholder - Placeholder of the text field.
 * @attr name - Field name submitted with the owning form.
 * @attr size - `sm` | `md` | `lg`.
 * @attr first-day - Weekday column 0: `0` = Sunday, `1` = Monday (default).
 * @attr format - Display pattern; `YYYY`, `MM`, `M`, `DD` and `D` are replaced.
 * @fires an-date-change - Fired when a day is picked, typed, cleared or reset; `detail: { value, originalEvent }`.
 * @fires an-date-open - Fired when the popover panel opens.
 * @fires an-date-close - Fired when the popover panel closes.
 * @slot label - Optional label rendered above the trigger.
 * @csspart base - Wrapper around the label, the trigger and the panel.
 * @csspart label - The visible label; hidden while the `label` slot is empty.
 * @csspart trigger - The clickable field that opens the panel.
 * @csspart input - The internal native `<input role="combobox">`.
 * @csspart panel - The calendar dialog.
 * @csspart header - Month bar holding the title and the two arrows.
 * @csspart title - The `YYYY年M月` title.
 * @csspart nav-prev - Previous-month button.
 * @csspart nav-next - Next-month button.
 * @csspart grid - The 6 x 7 `role="grid"` container.
 * @csspart weekday - One weekday column header.
 * @csspart day - One day button.
 * @csspart day-selected - Added to the selected day.
 * @csspart day-today - Added to today.
 * @csspart day-outside - Added to days of the neighbouring months.
 * @csspart footer - Bottom bar with the clear and today buttons.
 * @csspart clear - Clears the selection.
 * @csspart today - Selects today.
 * @cssprop --an-date-height - Trigger height; defaults to `--an-space-11`.
 * @cssprop --an-date-bg - Trigger background; defaults to `--an-color-bg-1`.
 * @cssprop --an-date-fg - Trigger text colour; defaults to `--an-color-fg-1`.
 * @cssprop --an-date-border-color - Trigger border; defaults to `--an-color-border-1`.
 * @cssprop --an-date-radius - Trigger radius; defaults to `--an-radius-md`.
 * @cssprop --an-date-font-size - Trigger font size; defaults to `--an-font-size-md`.
 * @cssprop --an-date-padding-x - Trigger horizontal padding; defaults to `--an-space-3`.
 * @cssprop --an-date-focus-ring - Focus ring colour; defaults to `--an-color-accent-9`.
 * @cssprop --an-date-muted-fg - Muted text (weekdays, outside days); defaults to `--an-color-gray-9`.
 * @cssprop --an-date-panel-bg - Panel background; defaults to `--an-color-bg-1`.
 * @cssprop --an-date-panel-fg - Panel text colour; defaults to `--an-color-fg-1`.
 * @cssprop --an-date-panel-border-color - Panel border; defaults to `--an-color-border-1`.
 * @cssprop --an-date-panel-radius - Panel radius; defaults to `--an-radius-lg`.
 * @cssprop --an-date-panel-shadow - Panel shadow.
 * @cssprop --an-date-day-size - Day button size; defaults to `2.25rem`.
 * @cssprop --an-date-day-hover-bg - Day hover background; defaults to `--an-color-gray-2`.
 * @cssprop --an-date-day-selected-bg - Selected day background; defaults to `--an-color-accent-9`.
 * @cssprop --an-date-day-selected-fg - Selected day text; defaults to `#ffffff`.
 * @cssprop --an-date-today-ring - Ring drawn around today; defaults to `--an-color-accent-9`.
 */
export class AnDate extends AnElement {
  static override styles: string = `${panelStyles}\n${dateStyles}`;

  static override formAssociated = true;

  static override defaults = {
    ...SHARED_DEFAULTS,
    format: 'YYYY-MM-DD',
    placeholder: '请选择日期',
    readonly: false,
  };

  static override get observedAttributes(): string[] {
    return [...super.observedAttributes, 'value', 'aria-label', 'aria-labelledby'];
  }

  /** Display pattern of the trigger text. */
  declare format: string;
  declare min: string;
  declare max: string;
  /** Controlled open state of the popover panel; reflects to the `open` attribute. */
  declare open: boolean;
  declare inline: boolean;
  declare disabled: boolean;
  declare required: boolean;
  declare placeholder: string;
  declare name: string;
  declare size: string;
  declare firstDay: number;

  /** Shows the value but forbids picking and typing. */
  declare readonly: boolean;

  #panel: DatePanelController;
  #formDisabled = false;
  #value: ISODate = '';
  #initialValue: ISODate = '';
  #initialCaptured = false;

  constructor() {
    super();
    this.#panel = new DatePanelController(this.#host());
    this.#panel.listen();
  }

  /** Selected day in `YYYY-MM-DD`; `''` when empty. */
  get value(): ISODate {
    return this.#value;
  }

  set value(next: ISODate) {
    this.#setValue(next);
  }

  /** Read-only alias of the controlled `open` state. */
  get isOpen(): boolean {
    return this.open;
  }

  /** Opens the panel; no-op when `inline`, `disabled` or `readonly`. */
  show(): void {
    if (this.inline || this.#blocked) return;
    this.open = true;
  }

  /** Closes the panel by clearing the controlled `open` state. */
  close(): void {
    this.open = false;
  }

  /** Flips the open state: `close()` while open, `show()` while closed. */
  toggle(): void {
    if (this.open) this.close();
    else this.show();
  }

  override attributeChangedCallback(
    name: string,
    oldValue: string | null,
    value: string | null,
  ): void {
    if (name === 'value') {
      if (oldValue !== value) this.#setValue(value ?? '');
      return;
    }
    if (name === 'aria-label' || name === 'aria-labelledby') {
      this.requestUpdate();
      return;
    }
    super.attributeChangedCallback(name, oldValue, value);
    this.#panel.attributeChanged(name, oldValue, value);
    if (name === 'readonly' && value !== null) this.#panel.blockedChanged();
  }

  override requestUpdate(): void {
    this.#panel.captureFocus();
    super.requestUpdate();
  }

  protected override render(): string {
    return (
      `<div class="base" part="base">` +
      this.#panel.renderLabel() +
      (this.inline ? '' : this.#panel.renderTrigger()) +
      this.#panel.renderPanel() +
      `</div>`
    );
  }

  protected override afterRender(): void {
    this.#syncForm();
    this.#panel.afterRender();
  }

  protected override onConnect(): void {
    this.#panel.connect();
    if (!this.#initialCaptured) {
      this.#initialCaptured = true;
      this.#initialValue = this.#value;
    }
    this.#syncForm();
  }

  protected override onDisconnect(): void {
    this.#panel.disconnect();
  }

  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    if (disabled) this.close();
    this.requestUpdate();
  }

  protected override onFormReset(): void {
    this.#value = this.#initialValue;
    this.close();
    this.requestUpdate();
  }

  /** Rows this element contributes to `FormData`; empty values submit nothing. */
  protected override formEntries(): Array<[string, string | File]> {
    if (this.name.length === 0 || this.#value === '') return [];
    return [[this.name, this.#value]];
  }

  get #blocked(): boolean {
    return this.disabled || this.readonly || this.#formDisabled;
  }

  #syncForm(): void {
    const internals = this.internals;
    if (internals === null) return;
    const value = this.#value;
    // A disabled control is left out of the form entry list entirely.
    if (this.name.length === 0 || value === '' || this.disabled || this.#formDisabled) {
      internals.setFormValue(null);
    } else {
      internals.setFormValue(value);
    }

    const missing =
      this.required && value === '' && !this.readonly && !this.disabled && !this.#formDisabled;
    if (missing) {
      internals.setValidity({ valueMissing: true }, REQUIRED_MESSAGE, this.#input() ?? undefined);
    } else {
      internals.setValidity({});
    }
  }

  #setValue(next: string): void {
    const value = isValidISO(next) ? next : '';
    if (value === this.#value) return;
    this.#value = value;
    this.requestUpdate();
  }

  #commitDay(iso: ISODate, originalEvent: Event): void {
    if (this.#blocked) return;
    this.#setValue(iso);
    this.emit<AnDateChangeDetail>('an-date-change', { value: this.#value, originalEvent });
    if (!this.inline) {
      this.close();
      this.#panel.focusTrigger();
    }
  }

  #clearSelection(originalEvent: Event): void {
    if (this.#value === '') return;
    this.#setValue('');
    this.emit<AnDateChangeDetail>('an-date-change', { value: '', originalEvent });
  }

  #commitInput(raw: string, originalEvent: Event): void {
    if (this.#blocked) return;
    const text = raw.trim();
    if (text === '') {
      this.#clearSelection(originalEvent);
      return;
    }
    if (!isValidISO(text) || this.#outsideRange(text)) {
      // Invalid or out of range: put the previous formatted value back.
      this.requestUpdate();
      return;
    }
    if (text !== this.#value) {
      this.#setValue(text);
      this.emit<AnDateChangeDetail>('an-date-change', { value: this.#value, originalEvent });
    }
    if (!this.inline && originalEvent.type === 'keydown') this.close();
  }

  #outsideRange(iso: ISODate): boolean {
    if (isValidISO(this.min) && compareISO(iso, this.min) < 0) return true;
    if (isValidISO(this.max) && compareISO(iso, this.max) > 0) return true;
    return false;
  }

  #input(): HTMLInputElement | null {
    return this.shadowRoot?.querySelector<HTMLInputElement>('input[data-focus="input"]') ?? null;
  }

  /** Adapter the shared controller talks to; keeps this class' API private. */
  #host(): DateHost {
    const element = this;
    return {
      element,
      get inline() {
        return element.inline;
      },
      get disabled() {
        return element.disabled;
      },
      get blocked() {
        return element.#blocked;
      },
      get formDisabled() {
        return element.#formDisabled;
      },
      get firstDay() {
        return element.firstDay;
      },
      get min() {
        return element.min;
      },
      get max() {
        return element.max;
      },
      get open() {
        return element.open;
      },
      get selectedDays() {
        return element.#value === '' ? [] : [element.#value];
      },
      get rangePreview() {
        return null;
      },
      get canClear() {
        return element.#value !== '' && !element.#blocked;
      },
      get displayText() {
        return element.#value === '' ? '' : formatDisplay(element.#value, element.format);
      },
      get placeholder() {
        return element.placeholder;
      },
      get inputReadonly() {
        return element.readonly;
      },
      get accessibleName() {
        return '日期';
      },
      get panelLabel() {
        return '选择日期';
      },
      get eventPrefix() {
        return 'an-date';
      },
      get emitPanelEvents() {
        return true;
      },
      show: () => this.show(),
      close: () => this.close(),
      setOpen: (next: boolean) => {
        this.open = next;
      },
      emitPanelEvent: (name: string) => {
        this.emit(name, {});
      },
      commitDay: (iso: ISODate, originalEvent: Event) => this.#commitDay(iso, originalEvent),
      clearSelection: (originalEvent: Event) => this.#clearSelection(originalEvent),
      commitInput: (raw: string, originalEvent: Event) => this.#commitInput(raw, originalEvent),
      onDayHover: () => {},
      requestUpdate: () => this.requestUpdate(),
    };
  }
}

export { SIZES };
